package com.jiugeng.erp.forwarder;
import java.io.*;import java.nio.file.*;import java.util.*;
import org.apache.poi.ss.usermodel.*;import org.apache.poi.ss.util.*;import org.apache.poi.hssf.usermodel.*;import org.apache.poi.xssf.usermodel.*;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@Component
class ForwarderWorkbook {
 private final Path root;
 ForwarderWorkbook(@Value("${erp.forwarder.template-dir:.local/templates/forwarders}") String root){this.root=Path.of(root);}
 Workbook open(String carrier)throws IOException{String file=switch(carrier){case "KAIQI"->"kaiqi-v1.xls";case "HUAMAO"->"huamao-v1.xlsx";default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"货代模板无效");};if(!Files.isRegularFile(root.resolve(file)))throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"货代模板未部署，请联系管理员");try(var input=Files.newInputStream(root.resolve(file))){return WorkbookFactory.create(input);}}
 Map<String,Object> options(String carrier){try(var wb=open(carrier)){var channels=new ArrayList<String>();if(carrier.equals("KAIQI"))for(Row r:wb.getSheet("渠道")){String country=value(r,4),channel=value(r,5);if(country.contains("美国")&&!channel.isBlank()&&!channels.contains(channel))channels.add(channel);}var addresses=new ArrayList<Map<String,String>>();Sheet s=wb.getSheet(carrier.equals("KAIQI")?"《美国AMZ地址库》":"仓库代码地址");for(Row r:s){if(r.getRowNum()==0)continue;var m=new LinkedHashMap<String,String>();if(carrier.equals("KAIQI")){String code=value(r,1);if(code.isBlank())continue;m.put("code",code);m.put("postalCode",value(r,14));m.put("consignee",value(r,4));m.put("company",value(r,5));m.put("phone",value(r,6));m.put("address",value(r,8));m.put("address2",value(r,9));m.put("city",value(r,11));m.put("region",value(r,12));}else{m.put("code",value(r,0));m.put("postalCode",value(r,5));m.put("consignee",value(r,6));m.put("company",value(r,8));m.put("phone",value(r,7));m.put("address",value(r,4));m.put("city",value(r,3));m.put("region",value(r,2));}String phone=m.getOrDefault("phone","").replaceAll("[^0-9]","");if(phone.matches("0?1234567[0-9]*")||phone.matches("([0-9])\\1{5,}"))m.put("phone","");addresses.add(m);}return Map.of("channels",channels,"addresses",addresses,"templateVersion","v1");}catch(IOException e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"模板读取失败");}}
 private static String value(Row r,int c){Cell cell=r.getCell(c);return cell==null?"":new DataFormatter().formatCellValue(cell).trim();}
 byte[] export(ForwarderDocuments.Document d){ForwarderDocuments.complete(new ForwarderDocuments.Input(d.documentNo(),d.carrier(),d.status(),d.fields(),d.items(),d.version()));try(var w=open(d.carrier());var out=new ByteArrayOutputStream()){
  Sheet s=w.getSheetAt(0);boolean k=d.carrier().equals("KAIQI");int first=k?14:11,cols=k?23:16;Row sample=s.getRow(first);CellStyle[] styles=new CellStyle[cols];for(int i=0;i<cols;i++)styles[i]=sample.getCell(i,Row.MissingCellPolicy.CREATE_NULL_AS_BLANK).getCellStyle();float height=sample.getHeightInPoints();
  if(s.getDrawingPatriarch() instanceof HSSFPatriarch drawing)for(var child:List.copyOf(drawing.getChildren()))if(child instanceof HSSFPicture)drawing.removeShape(child);
  if(s.getDrawingPatriarch() instanceof XSSFDrawing drawing){var ct=drawing.getCTDrawing();while(ct.sizeOfTwoCellAnchorArray()>0)ct.removeTwoCellAnchor(0);while(ct.sizeOfOneCellAnchorArray()>0)ct.removeOneCellAnchor(0);while(ct.sizeOfAbsoluteAnchorArray()>0)ct.removeAbsoluteAnchor(0);}
  for(int i=first;i<=s.getLastRowNum();i++){Row row=s.getRow(i);if(row!=null)for(Cell cell:row)cell.setBlank();}
  var f=d.fields();if(k){String[][] map={{"B3","waybill"},{"B4","reference"},{"B6","country"},{"B7","channel"},{"B8","customsType"},{"B9","insured"},{"B10","insurance"},{"B11","battery"},{"B12","magnet"},{"D3","warehouse"},{"D4","postalCode"},{"D5","consignee"},{"D6","phone"},{"D7","city"},{"D8","region"},{"D9","address"},{"D10","address2"},{"D11","company"}};for(var m:map)set(s,m[0],f.get(m[1]));numeric(s,"B5",ForwarderDocuments.boxes(d.items()));if(!f.get("insurance").isBlank())numeric(s,"B10",Double.parseDouble(f.get("insurance")));}
  else{String[][] map={{"B3","waybill"},{"B4","shipper"},{"F4","shipperVat"},{"B5","shipperCompany"},{"B6","shipperAddress"},{"B7","shipperCity"},{"F7","shipperRegion"},{"B8","shipperPostalCode"},{"F8","shipperPhone"},{"B9","extraService"},{"B10","notes"},{"H3","consignee"},{"H4","company"},{"H5","country"},{"M5","postalCode"},{"H6","address"},{"H7","city"},{"M7","region"},{"H8","phone"},{"M8","warehouse"},{"H9","consigneeVat"},{"M9","consigneeEori"}};for(var m:map)set(s,m[0],f.get(m[1]));set(s,"H6",f.get("address")+(f.get("address2").isBlank()?"":", "+f.get("address2")));numeric(s,"F3",ForwarderDocuments.boxes(d.items()));Sheet imp=w.getSheet("进口商");String[][] imports={{"B2","importer"},{"I2","importerCompany"},{"B3","importerPhone"},{"I3","importerPostalCode"},{"B4","importerCountry"},{"I4","importerRegion"},{"B5","importerCity"},{"I5","importerTax"},{"B6","importerAddress"}};for(var m:imports)set(imp,m[0],f.get(m[1]));}
  var items=new ArrayList<>(d.items());items.sort(Comparator.comparingInt(r->ForwarderDocuments.number(r,"boxStart").intValue()));var pictures=new HashMap<String,Integer>();int target=first;var groups=new LinkedHashMap<String,List<Integer>>();
  for(var item:items){int count=ForwarderDocuments.number(item,"boxCount").intValue(),start=ForwarderDocuments.number(item,"boxStart").intValue();for(int box=0;box<(k?count:1);box++){
   Row r=s.getRow(target);if(r==null)r=s.createRow(target);r.setHeightInPoints(Math.max(height,70));for(int c=0;c<cols;c++){Cell cell=r.getCell(c,Row.MissingCellPolicy.CREATE_NULL_AS_BLANK);cell.setBlank();cell.setCellStyle(styles[c]);}
   if(k){num(r,0,start+box);str(r,1,item.get("boxCode").isBlank()?item.get("fba")+"U"+String.format("%06d",start+box):item.get("boxCode")+String.format("%06d",start+box));String[] keys={"fba","reference","name","nameEn","hsCode","price","perBox"};for(int i=0;i<keys.length;i++)put(r,i+2,item,keys[i]);num(r,9,ForwarderDocuments.number(item,"perBox").doubleValue());num(r,10,ForwarderDocuments.number(item,"perBox").multiply(ForwarderDocuments.number(item,"price")).doubleValue());String[] more={"brand","brandType","model","material","usage"};for(int i=0;i<more.length;i++)put(r,i+11,item,more[i]);num(r,17,1);String[] dims={"netWeight","grossWeight","length","width","height"};for(int i=0;i<dims.length;i++)put(r,i+18,item,dims[i]);}
   else{String[] keys={"fba","reference"};for(int i=0;i<2;i++)put(r,i,item,keys[i]);str(r,2,item.get("length")+"*"+item.get("width")+"*"+item.get("height"));put(r,3,item,"boxCount");put(r,4,item,"grossWeight");String[] other={"hsCode","name","nameEn","perBox","price","brand","model","material","usage"};for(int i=0;i<other.length;i++)put(r,i+5,item,other[i]);str(r,15,item.get("sku"));groups.computeIfAbsent(start+":"+count,x->new ArrayList<>()).add(target);}
   Integer index=pictures.get(item.get("image"));if(index==null){index=w.addPicture(ForwarderDocuments.image(item.get("image")),Workbook.PICTURE_TYPE_PNG);pictures.put(item.get("image"),index);}addPicture(w,s,r,k?16:14,index,item.get("image"));target++;
  }}
  if(!k)for(var group:groups.values())if(group.size()>1)for(int col:List.of(2,3,4)){for(int i=1;i<group.size();i++)s.getRow(group.get(i)).getCell(col).setBlank();s.addMergedRegion(new CellRangeAddress(group.get(0),group.get(group.size()-1),col,col));}
  w.setForceFormulaRecalculation(false);w.write(out);return out.toByteArray();
 }catch(IOException e){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"模板导出失败，请重试");}}
 static void addPicture(Workbook w,Sheet s,Row row,int col,int index,String uri)throws IOException{
  var image=javax.imageio.ImageIO.read(new ByteArrayInputStream(ForwarderDocuments.image(uri)));double cw=s.getColumnWidthInPixels(col),rh=row.getHeightInPoints()*96/72,scale=Math.min((cw-8)/image.getWidth(),(rh-8)/image.getHeight());double width=image.getWidth()*scale,height=image.getHeight()*scale,left=(cw-width)/2,top=(rh-height)/2;
  var a=w.getCreationHelper().createClientAnchor();a.setCol1(col);a.setCol2(col);a.setRow1(row.getRowNum());a.setRow2(row.getRowNum());a.setAnchorType(ClientAnchor.AnchorType.MOVE_AND_RESIZE);
  double dx=w instanceof HSSFWorkbook?1024/cw:9525,dy=w instanceof HSSFWorkbook?256/rh:9525;a.setDx1((int)(left*dx));a.setDx2((int)((left+width)*dx));a.setDy1((int)(top*dy));a.setDy2((int)((top+height)*dy));s.createDrawingPatriarch().createPicture(a,index);
 }
 static Cell cell(Sheet s,String address){var ref=new CellReference(address);Row r=s.getRow(ref.getRow());if(r==null)r=s.createRow(ref.getRow());return r.getCell(ref.getCol(),Row.MissingCellPolicy.CREATE_NULL_AS_BLANK);}
 static void set(Sheet s,String address,String value){Cell c=cell(s,address);c.setBlank();if(value!=null&&!value.isEmpty())c.setCellValue(value);}
 static void numeric(Sheet s,String address,double value){Cell c=cell(s,address);c.setBlank();c.setCellValue(value);}
 static void str(Row r,int col,String value){if(value==null||value.isEmpty())r.getCell(col).setBlank();else r.getCell(col).setCellValue(value);}
 static void num(Row r,int col,double value){r.getCell(col).setCellValue(value);}
 static void put(Row r,int col,Map<String,String> item,String key){String value=item.get(key);if(ForwarderDocuments.NUMBERS.contains(key)&&!value.isBlank())num(r,col,Double.parseDouble(value));else str(r,col,value);}
}
